head.script:
scwin.screenId = "jldstf07410";

///////// 1. 변수 및 선언 영역 /////////

scwin.toolTip = $c.util.getComponent('toolTip');

scwin.frame = undefined;

scwin.resultProcs = "";


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bzProcsNo"))); } },
        { childId: "ipt_listTpClssCd", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("listTpClssCd"))); } },
        { childId: "ipt_bzProcsNo_2", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bzProcsNo"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        form = (document.preListForm || { elements: [] });
        scwin.setEditMode(null);
        loadTp = 'null';
        if ("32" !== "${commonInfo. list_procs_stat_cd}") {
            $c.util.getComponent('AcptBttn').visable = false;
            $c.util.getComponent('img_9').visable = false;
            $c.util.getComponent('AcptBttn').src = "/img/btn_Acpt_d.gif";
            $c.util.getComponent('img_9').src = "/img/btn_reject_d.gif";
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07410.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldstf07410: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07410.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_doProcs_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_doProcs_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_doProcs_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.doProcs(33)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07410.btn_doProcs_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_doProcs_2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_doProcs_2_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_doProcs_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.doProcs(37)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07410.btn_doProcs_2_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_formFileList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_formFileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_attachList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_attachList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["useYn"]==='Y') { if (typeof scwin.downloadFile === 'function') { await scwin.downloadFile(r["attachFileSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.downloadFile (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formFileList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.grd_formFileList_2_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_formFileList_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_attachList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_attachList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: downloadFile (인자 미해석) */
        if (r["useYn"]==='Y') { if (typeof scwin.downloadFile === 'function') { await scwin.downloadFile(r["attachFileSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.downloadFile (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formFileList_2.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_downloadFile = async function () {
    const sbmOptions = {
        id: "tx_downloadFile",
        method: "post",
        action: "/konex/ListPrelmInvstgKonex.do",
        ref: "dma_downloadFileReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07410.tx_downloadFile" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_doProcs_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_doProcs_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_doProcs_xhr", unresolved: "action:self_submit:tx_doProcs_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_formFileList_2_fmt_column3
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_formFileList_2_fmt_column3 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_attachList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "useYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: column3 (image)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_formFileList_2.column3" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.setEditMode
 * @author Inswave
 * @date 2026. 09. 29
 * @param tp
 * @returns
 * @hidden N
*/
scwin.setEditMode = function (tp) {
    /* sdd-asis-lifecycle:begin setEditMode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    let div;
    let files;
    const chkObj = document.getElementsByName('useYn');
    //var editObj = document.getElementsByName('editYn');
    const itmObj = document.getElementsByName('fileItmNm');
    //var remkObj = document.getElementsByName('remk');	

    for(var i = 0;i<chkObj.length;i++){
        //files = form['attachFiles['+i+']'];
        //files.disabled = true;
        chkObj[i].disabled = true;
        itmObj[i].readOnly = true;
        //remkObj[i].readOnly = true;
    }

    for(var i = "${fn:length(formFileList)}";i<chkObj.length;i++){		
        chkObj[i].checked = true;
    }


    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNotRelated
 * @author Inswave
 * @date 2026. 09. 29
 * @param tmpObj
 * @returns
 * @hidden N
*/
scwin.isNotRelated = function (tmpObj) {
    /* sdd-asis-lifecycle:begin isNotRelated — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const objIdx = scwin.getObjIdx(tmpObj, tmpObj.name);
    const fileObj = form['attachFiles['+ objIdx +']'];
    const itmObj = document.getElementsByName('fileItmNm');
    if (tmpObj.checked === true) {
        fileObj.disabled = true;
        if (objIdx >= $) {
            fn: length(formFileList);
        }
        itmObj[objIdx].readOnly = true;
    } else {
        fileObj.disabled = false;
        if (objIdx >= $) {
            fn: length(formFileList);
        }
        itmObj[objIdx].readOnly = false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getObjIdx
 * @author Inswave
 * @date 2026. 09. 29
 * @param tmpObj ver
 * @returns
 * @hidden N
*/
scwin.getObjIdx = function (tmpObj, ver) {
    /* sdd-asis-lifecycle:begin getObjIdx — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let idx;
    const chkObj = document.getElementsByName(ver);
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i] === '[object]') {
            if (chkObj[i] === tmpObj) {
                idx = i;
                break;
            }
        }
    }
    return idx;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.hideTitle
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.hideTitle = function (ver) {
    /* sdd-asis-lifecycle:begin hideTitle — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.toolTip.style.visibility = "hidden";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doProcs
 * @author Inswave
 * @date 2026. 09. 29
 * @param listProcsStatCd
 * @returns
 * @hidden N
*/
scwin.doProcs = async function (listProcsStatCd) {
    /* sdd-asis-lifecycle:begin doProcs — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ("32" !== "${commonInfo. list_procs_stat_cd}") {
        await $c.win.alert(" 이미 처리된 건입니다.");
        return;
    }
    let msg = null;
    const msg1 = "접수처리 하시겠습니까?";
    const msg2 = "반려처리 하시겠습니까?";
    const msg3 = "위원회 심사대상으로 설정하시겠습니까?";
    const isComiteYn = null;
    if ("33" === listProcsStatCd) {
        msg = msg1;
    } else {
        msg = msg2;
    }
    const rse = await $c.win.confirm(msg, 1);
    if (!rse) {
        return;
    } else {

    }
    let url = '/konex/LstInvstgKonexCommon.do?method=processPremInvstgApp';
    url += "&BZ_PROCS_NO=" + $c.util.getComponent('ipt_bzProcsNo').getValue();
    url += "&LIST_INVSTG_BZ_TP_CD=120";
    url += "&LIST_PROCS_STAT_CD=" + listProcsStatCd;
    url += "&PROCS_EMP_NO=" + $c.session.getUserInfo("empNo");
    url += "&COMITE_INVSTG_OBJ_YN=" + isComiteYn;
    const frm = (document.procsForm || { elements: [] });
    frm.action = url;
    await scwin.tx_doProcs_xhr();
    const fr_fn_list_sync = $c.frame.Provider("../").fn_list_sync;
    fr_fn_list_sync();
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseXML
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = async function (responseXML) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((responseXML == null) || ('' === responseXML)) {
        await $c.win.alert("처리 중 오류가 발생하였습니다.");
    } else {
        const xmlDoc = xmlHttp.responseXML;
        let resultProcs = "";
        resultProcs = xmlDoc.getElementsByTagName("result")[0].firstChild.nodeValue;
        if (("" !== resultProcs) && ("-1" !== resultProcs)) {
            await $c.win.alert("정상처리되었습니다.");
            $c.util.getComponent('AcptBttn').visable = false;
            $c.util.getComponent('img_9').visable = false;
            $c.util.getComponent('AcptBttn').src = "/img/btn_Acpt_d.gif";
            $c.util.getComponent('img_9').src = "/img/btn_reject_d.gif";
        } else {
            await $c.win.alert("비정상 처리되었습니다.");
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param attachFileSeq
 * @returns
 * @hidden N
*/
scwin.downloadFile = async function (attachFileSeq) {
    /* sdd-asis-lifecycle:begin downloadFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    const gubun = "" + dma_pageContext.get("listTpClssCd") + "" ;
    if( $c.session.getUserInfo("depCd") === '3B30' || $c.session.getUserInfo("depCd") === '3B00' )  { //코넥스부서장(3B00) 추가
        const obj = (document.downloadForm || { elements: [] });
        obj.action='/konex/ListPrelmInvstgKonex.do';
        $c.util.getComponent("dma_downloadFileReq").set("method", 'downloadFile');
        $c.util.getComponent("dma_downloadFileReq").set("attachFileSeq", attachFileSeq);
        await scwin.tx_downloadFile();		
    }else {
        await $c.win.alert('파일 열람 권한이 없습니다');
    }

    /* sdd-asis-lifecycle:end */
};
